 549					`OAuth refresh failed for ${provider}: ${response.status}${detail ? ` ${detail.slice(0, 240)}` : ""}`,
 550				);
 551				return null;
 552			}
 553	
 554			const tokens = await response.json();
 555	
 556			const newCredentials: OAuthCredentials = {
 557				refresh: tokens.refresh_token ?? credentials.refresh,
 558				access: tokens.access_token,
 559				expires: Date.now() + (tokens.expires_in ?? 3600) * 1000,
 560				provider,
 561				apiKey: provider === "openai-codex"
 562					? undefined
 563					: typeof tokens.api_key === "string" ? tokens.api_key : credentials.apiKey,
 564				idToken: typeof tokens.id_token === "string" ? tokens.id_token : credentials.idToken,
 565			};
 566	
 567			await saveOAuthCredentials(newCredentials);
 568			return newCredentials;
 569		} catch (error) {
 570			console.warn(
 571				`OAuth refresh request failed for ${provider}: ${error instanceof Error ? error.message : String(error)}`,
 572			);
 573			return null;
 574		}
 575	}
