   2	import { trustedOrigin } from "./security.js";
   3	
   4	type MediaKind = "audio" | "video" | "unknown";
   5	
   6	export interface DesktopPermissionDecision {
   7		ownerMatches: boolean;
   8		permission: string;
   9		requestingOrigin?: string;
  10		isMainFrame: boolean;
  11		mediaTypes?: readonly MediaKind[];
  12	}
  13	
  14	/**
  15	 * Keep the preload-bearing renderer fail closed. Camera and microphone are the
  16	 * only browser permissions Keating currently needs, and only its own main frame
  17	 * may request them. Screen capture remains denied until the desktop app exposes
  18	 * a learner-visible source picker.
  19	 */
  20	export function isAllowedDesktopPermission(
  21		request: DesktopPermissionDecision,
  22		appOrigin: string,
  23	): boolean {
  24		if (!request.ownerMatches || request.permission !== "media" || !request.isMainFrame) {
  25			return false;
  26		}
  27		if (trustedOrigin(request.requestingOrigin ?? "") !== appOrigin) return false;
  28		const mediaTypes = request.mediaTypes ?? [];
  29		return mediaTypes.length > 0
  30			&& mediaTypes.every((type) => type === "audio" || type === "video");
  31	}
  32	
  33	export function installDesktopPermissionPolicy(
  34		window: BrowserWindow,
  35		appOrigin: string,
  36	): () => void {
  37		const session: Session = window.webContents.session;
  38		session.setPermissionCheckHandler((requestingWebContents, permission, requestingOrigin, details) => {
  39			return isAllowedDesktopPermission({
  40				ownerMatches: requestingWebContents === window.webContents,
  41				permission,
  42				requestingOrigin: details.securityOrigin ?? requestingOrigin ?? details.requestingUrl,
  43				isMainFrame: details.isMainFrame,
  44				mediaTypes: details.mediaType ? [details.mediaType] : [],
  45			}, appOrigin);
  46		});
  47		session.setPermissionRequestHandler((requestingWebContents, permission, callback, details) => {
  48			const mediaDetails = details as typeof details & {
  49				securityOrigin?: string;
  50				mediaTypes?: MediaKind[];
  51			};
  52			callback(isAllowedDesktopPermission({
  53				ownerMatches: requestingWebContents === window.webContents,
  54				permission,
  55				requestingOrigin: mediaDetails.securityOrigin ?? details.requestingUrl,
  56				isMainFrame: details.isMainFrame,
  57				mediaTypes: mediaDetails.mediaTypes,
  58			}, appOrigin));
  59		});
  60		// Never silently pick a monitor or window on the learner's behalf.
  61		session.setDisplayMediaRequestHandler((_request, callback) => callback({}));
  62	
  63		return () => {
  64			session.setPermissionCheckHandler(null);
  65			session.setPermissionRequestHandler(null);
  66			session.setDisplayMediaRequestHandler(null);
  67		};
  68	}
